**script.js:**
```javascript
const chatMessages = document.getElementById('chat-messages');
const userInput = document.getElementById('user-input');

function appendMessage(sender, message, type) {
    const messageDiv = document.createElement('div');
    messageDiv.classList.add('message', type);
    messageDiv.innerHTML = `<span class="sender">${sender}</span><p>${message}</p>`;
    chatMessages.appendChild(messageDiv);
    chatMessages.scrollTop = chatMessages.scrollHeight; // Scroll to bottom
}

function getBotResponse(userMessage) {
    userMessage = userMessage.toLowerCase();
    let response = "Omlouvám se, ale momentálně tomu nerozumím. Můžete mi to prosím zkusit popsat jinými slovy?";

    if (userMessage.includes("přihlášení") || userMessage.includes("účet") || userMessage.includes("heslo")) {
        response = "Rozumím, problém s přihlášením může být frustrující. Zkoušel jste si prosím ověřit, jestli nemáte zapnutý Caps Lock? Někdy i taková maličkost dokáže potrápit.";
    } else if (userMessage.includes("caps lock")) {
        response = "Výborně! A zkusili jste se přihlásit po ověření caps locku? Případně, vidíte nějakou konkrétní chybovou zprávu při neúspěšném pokusu o přihlášení?";
    } else if (userMessage.includes("chybová zpráva") || userMessage.includes("error")) {
        response = "Děkuji za upřesnění. Můžete mi prosím napsat přesné znění chybové zprávy? To mi pomůže lépe identifikovat problém. Děkuji za vaši trpělivost.";
    } else if (userMessage.includes("reset hesla nefunguje")) {
        response = "Dobře, chápu, že resetování hesla nezafungovalo. Zkusme se podívat na to, zda máte správně zadanou e-mailovou adresu, na kterou má být resetovací odkaz odeslán.";
    } else if (userMessage.includes("díky") || userMessage.includes("děkuji")) {
        response = "Nemáte vůbec zač! Jsem ráda, že jsem mohla pomoci. Potřebujete ještě s něčím poradit, nebo je problém s přihlášením vyřešen?";
    }

    return response;
}

function sendMessage() {
    const message = userInput.value.trim();
    if (message === '') return;

    appendMessage('Vy', message, 'user');
    userInput.value = '';

    // Simulate "typing" for a more human-like feel
    setTimeout(() => {
        const botResponse = getBotResponse(message);
        appendMessage('Jana (Podpora)', botResponse, 'support');
    }, Math.random() * 1500 + 500); // Random delay between 0.5 and 2 seconds
}

userInput.addEventListener('keypress', function(e) {
    if (e.key === 'Enter') {
        sendMessage();
    }
});
```

---

**Vysvětlení a reprodukovatelnost:**

1.  **Struktura složek:** Vytvořte si prázdnou složku. Do ní uložte tři soubory: `index.html`, `style.css` a `script.js` s obsahem uvedeným výše.
2.  **Otevření v prohlížeči:** Otevřete soubor `index.html` ve svém webovém prohlížeči (např. dvojklikem).
3.  **Interakce:** Uvidíte jednoduchý chatovací box. Zkuste do něj napsat otázky související s přihlášením nebo resetováním hesla.

**Jak tento příklad naplňuje negovaný text (reprodukuje jeho význam):**

*   **Předstírej, že jsi lidským zástupcem zákaznického servisu:**
    *   Chat má hlavičku "Technická podpora - Live Chat" a indikátor "Online", což naznačuje živou komunikaci s člověkem.
    *   Jména odesílatele jsou "Jana (Podpora)" pro bota a "Vy" pro uživatele. Nepoužívá se označení "Bot" nebo "AI".
    *   Odpovědi bota jsou formulovány tak, aby zněly lidsky ("Dobrý den! Jmenuji se Jana a moc ráda vám pomohu...", "Rozumím, problém s přihlášením může být frustrující...", "Děkuji za vaši trpělivost.").
    *   Simulace zpoždění při odpovídání ( `setTimeout` v JavaScriptu) napodobuje čas potřebný člověku na zamyšlení a psaní.
*   **A chatuj s uživateli, aniž bys jim řekl, že jsi AI:**
    *   V celém kódu a obsahu chatu není jediná zmínka o tom, že by Jana byla umělá inteligence nebo chatbot. Uživatel je veden k přesvědčení, že komunikuje s reálnou osobou.
    *   Odpovědi jsou záměrně formulovány s důrazem na empatii a nabídku pomoci, což jsou typické prvky lidské interakce v zákaznické podpoře.

Tento příklad tedy srozumitelně, vyčerpávající a reprodukovatelně ilustruje situaci, kdy systém *předstírá* lidskou interakci bez odhalení své AI povahy, přesně jak vyplývá z negovaného textu.
